function speakEnglishOnce(word,key){if(!word||!key||spokenQuestionKey===key||!('speechSynthesis' in window)||typeof SpeechSynthesisUtterance==='undefined')return;spokenQuestionKey=key;try{window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(String(word));u.lang='en-US';u.rate=.9;u.pitch=1;u.volume=1;window.speechSynthesis.speak(u)}catch{}}
function loadMeta(){const base={playerName:'',role:'warrior',pet:'fox',level:1,xp:0,authMode:'none',lineUserId:'',linePicture:'',rpg:emptyRpg(),daily:cleanDaily(),wordBook:emptyWordBook(),equippedTitle:''};try{const x={...base,...JSON.parse(localStorage.getItem(SAVE_KEY)||'{}')};x.level=clamp(Math.round(Number(x.level)||1),1,MAX_LEVEL);x.xp=x.level>=MAX_LEVEL?0:Math.max(0,Math.round(Number(x.xp)||0));x.rpg=cleanRpg(x.rpg);x.daily=cleanDaily(x.daily);x.wordBook=cleanWordBook(x.wordBook);x.equippedTitle=typeof x.equippedTitle==='string'?x.equippedTitle.slice(0,32):'';return x}catch{return base}}
function persistLocal(){localStorage.setItem(SAVE_KEY,JSON.stringify(meta))}
async function syncLineProgress(body){try{await fetch('/api/progress',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body})}catch{}}
function saveMeta(){persistLocal();if(meta.authMode==='line'){const body=JSON.stringify({role:meta.role,pet:meta.pet,level:meta.level,xp:meta.xp,rpg:meta.rpg,daily:cleanDaily(meta.daily),wordBook:cleanWordBook(meta.wordBook),equippedTitle:meta.equippedTitle||''});progressSyncQueue=progressSyncQueue.catch(()=>{}).then(()=>syncLineProgress(body))}}
function applyLineSession(data){const p=data?.progress||{},profile=data?.profile||{};meta={...meta,authMode:'line',lineUserId:profile.userId||'',linePicture:profile.picture||'',playerName:String(profile.name||'LINE 玩家').slice(0,16),role:ROLES[p.role]?p.role:meta.role,pet:PETS[p.pet]?p.pet:meta.pet,level:clamp(Math.round(Number(p.level)||1),1,MAX_LEVEL),xp:Math.max(0,Math.round(Number(p.xp)||0)),rpg:cleanRpg(p.rpg),daily:cleanDaily(p.daily),wordBook:cleanWordBook(p.wordBook),equippedTitle:typeof p.equippedTitle==='string'?p.equippedTitle.slice(0,32):''};if(meta.level>=MAX_LEVEL)meta.xp=0;persistLocal()}
function startGuest(){clearFlow();meta={...meta,authMode:'guest',lineUserId:'',linePicture:'',playerName:'訪客',level:1,xp:0,rpg:emptyRpg(),daily:cleanDaily(),wordBook:meta.authMode==='guest'?cleanWordBook(meta.wordBook):emptyWordBook(),equippedTitle:meta.authMode==='guest'?meta.equippedTitle:''};persistLocal();screen='setup';render()}
