function beginStage(){clearFlow();answerFeedback=null;const s=stage();run.player.role=meta.role;run.player.pet=meta.pet;run.enemy=makeFighter({role:'monster',pet:null,monsterId:s.id,maxHp:s.hp,hp:s.hp,atk:s.atk,def:s.def,crit:s.crit});run.enemy.enraged=false;run.round=1;run.hand=dealHand(9,meta.role,run.level);run.enemyHand=dealHand(9);run.used=[];run.enemyUsed=[];run.selected=[];run.enemySelected=[];run.log=[];run.currentStep=null;run.stats=freshStats();run.wrongAnswers=[];run.dailyQuestionIndices=[];run.weaknessInjected=[];run.loadingQuestions=false;run.stageRewarded=false;run.lastReward=null;run.lastLoot=null;run.lastCrystals=0;run.ultimateEnergy=0;run.ultimateUsed=false;run.ultimateWindow=false;run.lootPlayed=false;run.towerRule=run.mode==='tower'?applyTowerRuleAtStart(run.player,run.enemy,run.towerFloor):null;const mythic=mythicEquipmentEffects(meta.rpg);if(mythic.startShieldPct>0)run.player.shield=Math.max(run.player.shield||0,Math.round(run.player.maxHp*mythic.startShieldPct));screen='cards';render()}
function startPk(){socialUI.leave();screen='pk';clearFlow();void preloadRoleAction(meta.role);pkMode?.stop(false);pkMode=createPkMode({app,meta,ROLES,PETS,visual,effects:ASSETS.effect,onExit:()=>{pkMode=null;screen='setup';render()},onSeasonResult:r=>{recordSeasonResult(r);logDaily('pk',1)},onQuizResult:correct=>{if(correct>0)logDaily('correct',correct)},onWordResults:recordPkVocabulary});pkMode.start()}

function uiImg(src,label,style=''){return `<img src="${esc(src)}" alt="${esc(label)}" style="${style}" decoding="async">`}
function imageButton(src,label,attrs=''){return `<button ${attrs} aria-label="${esc(label)}" style="border:0;background:transparent;padding:0;display:grid;place-items:center;width:100%;cursor:pointer">${uiImg(src,label,'display:block;max-width:100%;height:auto;object-fit:contain;')}</button>`}
function lootArt(item,className='loot-art'){const src=item?.art||lootImage(item),fallback=item?.quality==='mythic'?lootImage({...item,quality:'legendary'}):'',onerror=fallback?` onerror="this.onerror=null;this.src='${esc(fallback)}'"`:'';return src?`<img class="${esc(className)}" src="${esc(src)}" alt="${esc(item?.name||'裝備')}" decoding="async"${onerror}>`:''}
function systemBackButton(){return `<button class="system-back-btn" data-action="setup-back" aria-label="返回">${uiImg(ASSETS.ui.back,'返回','')}</button>`}
function renderHome(){return `<main class="home-screen"><section class="home-panel home-login"><button class="line-image-btn" data-action="line-login" aria-label="LINE 登入"></button></section><button class="fight-hotspot" data-action="guest-login" aria-label="訪客進入遊戲"></button></main>`}
function renderSetup(){const r=role(),g=growth(),col=collectionProgress(meta.rpg);return `<main class="setup-screen"><section class="setup-card"><section class="choice-section"><div class="choice-feature role-feature theme-${esc(meta.role)} growth-feature"><div class="growth-art role-growth-art">${uiImg(r.art,r.name,'')}</div>${growthPanel(g.role,'role')}</div><div class="choice-tabs">${Object.entries(ROLES).map(([id,x])=>`<button class="choice-tab ${meta.role===id?'active':''}" data-role="${id}">${esc(x.name)}</button>`).join('')}</div></section><section class="choice-section pet-section"><div class="choice-feature pet-feature theme-${esc(meta.pet)} growth-feature"><div class="growth-art pet-growth-art">${petImg(meta.pet)}</div>${growthPanel(g.pet,'pet')}</div><div class="choice-tabs">${Object.entries(PETS).map(([id,x])=>`<button class="choice-tab ${meta.pet===id?'active':''}" data-pet="${id}">${esc(petEnhanceLevel(id,meta.rpg)>=4?(x.awakening?.name||x.name):x.name)}</button>`).join('')}</div></section><div class="setup-actions setup-actions-four">${imageButton(ASSETS.ui.equipment,'裝備','data-action="equipment"')}${imageButton(ASSETS.ui.fight,'開始冒險','data-action="start"')}${imageButton(ASSETS.ui.pk,'線上對戰','data-action="pk"')}${imageButton(ASSETS.ui.petSkill,'寵物技能','data-action="pet-tree"')}${imageButton(ASSETS.ui.quest,'任務','data-action="quests"')}${imageButton(ASSETS.ui.achievement,'成就','data-action="achievements"')}${imageButton(ASSETS.ui.community,'社群','data-action="community"')}</div><div class="progression-actions"><button class="progression-btn tower-entry" data-action="tower" aria-label="試煉塔"></button><button class="progression-btn collection-entry" data-action="collection"><b>收藏圖鑑</b><small>${col.owned}/${col.total}</small></button></div></section></main>`}
function equipmentEnhanceButton(item){const info=equipmentEnhanceInfo(item),ready=info.level<10&&(meta.rpg.crystals||0)>=info.cost;return `<button class="mini-system-btn equip-upgrade-btn" data-enhance-equip="${esc(item.id)}" ${ready?'':'disabled'} aria-label="${esc(item.name)} +${info.level} 強化 ${info.cost} 結晶 成功率 ${Math.round(info.chance*100)}%">${info.level>=10?'已滿 +10':`強化 +${info.level} · ${info.cost}晶 · ${Math.round(info.chance*100)}%`}</button>`}
function equipmentSlot(id){const item=meta.rpg.inventory.find(x=>x.id===id);return `<div class="equip-slot">${item?`${lootArt(item,'equip-art')}<span class="quality-${esc(item.quality)}">${esc(item.name)}${item.enhance?` +${item.enhance}`:''}</span><small>${esc(itemBonusText(item))}</small>${equipmentEnhanceButton(item)}<button class="mini-system-btn" data-unequip="${esc(item.id)}">卸下</button>`:'<span class="empty-equip-slot">—</span>'}</div>`}
function equipmentGroup(label,kind,slots){return `<section class="equip-group ${esc(kind)}"><h2>${esc(label)}</h2><div class="equip-group-slots">${slots.join('')}</div></section>`}
function resonanceHtml(){const r=equipmentResonance(meta.rpg);return `<section class="resonance-panel">${r.recipes.map(x=>`<div class="resonance-chip ${x.active?'active':''}"><b>${esc(x.name)}</b><small>${esc(x.desc)}</small></div>`).join('')}</section>`}
function renderEquipment(){const eq=meta.rpg.equipped,rings=eq.rings||[],equipped=new Set([...eq.gems,eq.armor,...rings].filter(Boolean)),items=[...meta.rpg.inventory].filter(item=>!equipped.has(item.id)).sort((a,b)=>{const rank={common:0,rare:1,epic:2,legendary:3,mythic:4};return (rank[b.quality]??-1)-(rank[a.quality]??-1)||(Number(b.foundAt)||0)-(Number(a.foundAt)||0)});return `<main class="setup-screen system-screen"><section class="system-card"><div class="system-head">${systemBackButton()}<span></span><b class="crystal-count">結晶 ${meta.rpg.crystals||0}</b></div>${enhanceFeedback?`<p class="enhance-feedback" role="status">${esc(enhanceFeedback)}</p>`:''}<div class="equip-groups">${equipmentGroup('寶石','gems',[0,1,2].map(i=>equipmentSlot(eq.gems[i])))}${equipmentGroup('裝甲','armor',[equipmentSlot(eq.armor)])}${equipmentGroup('戒指','rings',[0,1].map(i=>equipmentSlot(rings[i])))}</div>${resonanceHtml()}<div class="inventory-list">${items.length?items.map(item=>{const full=(item.type==='gem'&&eq.gems.length>=3)||(item.type==='ring'&&rings.length>=2),syn=synthesisInfo(meta.rpg,item.id);return `<div class="loot-item quality-border-${esc(item.quality)}">${lootArt(item)}<div><b class="quality-${esc(item.quality)}">${esc(item.name)}${item.enhance?` +${item.enhance}`:''}</b><small>${esc(itemBonusText(item))}</small></div><div class="loot-item-actions">${equipmentEnhanceButton(item)}<button class="mini-system-btn" data-equip="${esc(item.id)}" ${full?'disabled':''}>裝備</button>${!['legendary','mythic'].includes(item.quality)?`<button class="mini-system-btn synth-btn" data-synthesize="${esc(item.id)}" ${syn.can?'':'disabled'}>合成 ${Math.min(3,syn.count)}/3</button>`:''}<button class="mini-system-btn crystal-btn" data-crystallize="${esc(item.id)}">結晶 +${crystalValue(item)}</button></div></div>`}).join(''):'<div class="empty-system">沒有多餘裝備</div>'}</div></section></main>`}
function renderPetTree(){
  const id=meta.pet,pet=petDisplay(id),paths=PET_PATHS[id]||[],tree=PET_TREES[id]||[],owned=new Set(meta.rpg.petSkills[id]||[]);
  const points=availableSkillPoints(meta.level,meta.rpg),crystals=meta.rpg.crystals||0,enhance=petEnhanceLevel(id,meta.rpg),cost=petEnhanceCost(id,meta.rpg),max=enhance>=4;
  const canEnhance=!max&&crystals>=cost,awakening=PET_AWAKENING[id];
  const petPicker=Object.keys(PETS).map(petId=>{
    const choice=petDisplay(petId),selected=id===petId;
    const count=(meta.rpg.petSkills[petId]||[]).length,all=PET_TREES[petId].length;
    return `<button type="button" class="pet-select-option ${selected?'active':''}" data-pet="${petId}" aria-pressed="${selected}">${petImg(petId,'pet-picker-art')}<b>${esc(choice.name)}</b><small>${count}/${all} 技能</small></button>`;
  }).join('');
  const skillLanes=paths.map((path,i)=>{
    const nodes=path.nodes.map((nodeId,tier)=>{
      const node=tree.find(item=>item.id===nodeId);
      if(!node)return '';
      const got=owned.has(node.id),ok=canUnlockPetSkill(id,node.id,meta.level,meta.rpg),required=petSkillPrerequisite(id,node.id);
      const previous=tree.find(item=>item.id===required),prerequisiteMissing=required&&!owned.has(required);
      const status=got?'已解鎖':prerequisiteMissing?`先解鎖「${previous?.name||'前置技能'}」`:points<node.cost?'技能點不足':'可解鎖';
      return `<div class="pet-skill-tier ${tier?'connected':''}"><span class="pet-skill-tier-number">${String(tier+1).padStart(2,'0')}</span><button type="button" class="pet-skill-node ${got?'unlocked':ok?'available':'locked'}" data-pet-skill="${id}|${node.id}" ${got||!ok?'disabled':''} aria-label="${esc(node.name)}：${esc(node.desc)}，${esc(status)}"><span class="pet-node-top"><b>${esc(node.name)}</b><em>${got?'✓ 已習得':`${node.cost} 點`}</em></span><small>${esc(node.desc)}</small><span class="pet-node-status">${esc(status)}</span></button></div>`;
    }).join('');
    return `<section class="pet-branch pet-branch-${i+1}" aria-label="${esc(path.name)}技能走向"><header class="pet-branch-head"><span class="pet-branch-index">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(path.name)}</h3><small>${esc(path.subtitle)}</small></div><strong>${path.nodes.filter(node=>owned.has(node)).length}/${path.nodes.length}</strong></header><p>${esc(path.description)}</p><div class="pet-branch-chain">${nodes}</div></section>`;
  }).join('');
  return `<main class="setup-screen system-screen"><section class="system-card pet-upgrade-screen"><div class="system-head">${systemBackButton()}<span>寵物專屬技能樹</span><b>${points} 點 · 結晶 ${crystals}</b></div><p class="pet-upgrade-intro">點選寵物，即可切換下方三條獨立養成路線。技能點由三隻寵物共用，每提升 1 級獲得 1 點；原有技能與強化進度保留。</p><div class="pet-upgrade-picker" aria-label="選擇要養成的寵物">${petPicker}</div><section class="pet-upgrade-feature theme-${esc(id)}"><div class="pet-upgrade-portrait">${petImg(id,'pet-upgrade-art')}</div><div class="pet-upgrade-detail"><span class="pet-upgrade-kicker">已選擇 · ${esc(pet.name)}</span><h2>${esc(pet.name)}養成</h2><p>${max?'已達覺醒 Lv.4/4':`強化 Lv.${enhance}/4 · 寵物能力 +${enhance*10}%`}</p><div class="pet-upgrade-controls"><span>結晶 ${crystals} · ${max?'已完成所有強化':`下次強化消耗 ${cost}`}</span><button class="mini-system-btn pet-enhance-btn" data-pet-enhance="${id}" ${canEnhance?'':'disabled'}>${max?'覺醒完成':'強化寵物'}</button></div>${max?`<div class="awakening-note"><b>${esc(awakening.name)}</b><small>${esc(awakening.desc)}</small></div>`:''}</div></section><div class="pet-tree-heading"><div><h2>三系技能養成</h2><p>三條路線可自由搭配，每條依序解鎖；已習得技能持續生效。</p></div><b>可用技能點 ${points}</b></div><div class="pet-root-connector" aria-hidden="true"><span>✦</span></div><p class="pet-branch-swipe">← 左右滑動，探索三種路線 →</p><div class="pet-branch-scroller"><div class="pet-branch-board">${skillLanes}</div></div><div class="pet-upgrade-footer"><small>重置會清空三隻寵物的技能並返還所有技能點；寵物強化與覺醒等級不會重置。</small><button class="secondary-btn reset-tree-btn" data-action="reset-pet-tree">重置全部技能樹</button></div></section></main>`;
}
function collectionTabs(){return `<nav class="collection-tabs" aria-label="圖鑑分類"><button data-collection-tab="equipment" class="${collectionTab==='equipment'?'active':''}">裝備圖鑑</button><button data-collection-tab="words" class="${collectionTab==='words'?'active':''}">單字圖鑑</button></nav>`}
function speakCollectedWord(index){const word=WORDS[index]?.[0];if(!word||typeof window==='undefined'||!window.speechSynthesis||typeof SpeechSynthesisUtterance==='undefined')return;try{window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(word);utterance.lang='en-US';utterance.rate=.85;window.speechSynthesis.speak(utterance)}catch{}}
function renderWordCollection(){
  const book=cleanWordBook(meta.wordBook),progress=wordBookProgress(book),filterChoices=[['all','全部'],['focus','重點詞彙'],['learning','學習中'],['mastered','精熟']];
  const statuses={focus:'重點詞彙',learning:'學習中',mastered:'精熟'};
  const matched=Object.entries(book.entries).map(([key,entry])=>({index:Number(key),entry,word:WORDS[Number(key)]?.[0]||'',meaning:WORDS[Number(key)]?.[1]||'',status:wordStatus(entry)})).filter(item=>item.word&&(wordFilter==='all'||item.status===statuses[wordFilter])&&(!wordSearch||item.word.toLowerCase().includes(wordSearch.toLowerCase())||item.meaning.includes(wordSearch))).sort((a,b)=>b.entry.lastAt-a.entry.lastAt||a.index-b.index);
  const pages=Math.max(1,Math.ceil(matched.length/36));wordPage=Math.min(Math.max(0,wordPage),pages-1);

  return `<main class="setup-screen system-screen"><section class="system-card collection-screen word-book-screen"><div class="system-head">${systemBackButton()}<span></span><b>${progress.mastered}/1200</b></div>${collectionTabs()}<div class="word-book-summary"><div><b>${progress.collected}</b><small>已收錄</small></div><div><b>${progress.learning}</b><small>學習中</small></div><div><b>${progress.focus}</b><small>重點詞彙</small></div><div><b>${progress.mastered}</b><small>精熟</small></div></div><div class="word-book-filters">${filterChoices.map(([id,label])=>`<button data-word-filter="${id}" class="${wordFilter===id?'active':''}">${label}</button>`).join('')}</div><div class="word-book-search"><input data-word-search-field type="search" maxlength="40" value="${esc(wordSearch)}" placeholder="搜尋已收錄的英文或中文" aria-label="搜尋單字"><button data-word-search-apply>搜尋</button></div><div class="word-book-grid">${matched.length?matched.slice(wordPage*36,(wordPage+1)*36).map(item=>`<button type="button" class="word-book-item status-${item.status==='精熟'?'mastered':item.status==='重點詞彙'?'focus':'learning'}" data-word-speak="${item.index}" aria-label="播放 ${esc(item.word)} 發音"><div class="word-book-item-title"><b>${esc(item.word)} <span aria-hidden="true">🔊</span></b><span>${esc(item.status)}</span></div><p>${esc(item.meaning)}</p></button>`).join(''):'<div class="word-book-empty">目前沒有符合條件的單字。作答後會逐步收錄。</div>'}</div><div class="word-book-paging"><button data-word-page="-1" ${wordPage===0?'disabled':''}>上一頁</button><span>${wordPage+1} / ${pages} 頁 · ${matched.length} 個單字</span><button data-word-page="1" ${wordPage>=pages-1?'disabled':''}>下一頁</button></div></section></main>`;
}
function renderCollection(){if(collectionTab==='words')return renderWordCollection();const entries=collectionEntries(),owned=new Set(meta.rpg.collection||[]),progress=collectionProgress(meta.rpg);return `<main class="setup-screen system-screen"><section class="system-card collection-screen"><div class="system-head">${systemBackButton()}<span></span><b>${progress.owned}/${progress.total}</b></div>${collectionTabs()}<div class="collection-grid">${entries.map(item=>{const got=owned.has(item.key);return `<div class="collection-card ${got?'owned':'locked'} quality-border-${esc(item.quality)}">${lootArt(item,'collection-art')}<b class="quality-${esc(item.quality)}">${esc(item.name)}</b><small>${got?esc(itemBonusText(item)):'尚未收集'}</small></div>`}).join('')}</div></section></main>`}

function statItem(src,value,label){return `<span class="battle-stat-line">${uiImg(src,label,'')}<b>${esc(value)}</b></span>`}
function stats(f){return `<div class="stat-row">${statItem(ASSETS.ui.hp,`${Math.max(0,Math.round(f.hp))}/${Math.round(f.maxHp)}`,'生命')}${statItem(ASSETS.ui.atk,Math.round(f.atk),'攻擊')}${statItem(ASSETS.ui.def,Math.round(f.def),'防禦')}${statItem(ASSETS.ui.crit,`${Math.round(f.crit*100)}%`,'爆擊率')}${statItem(ASSETS.ui.shield,Math.max(0,Math.round(f.shield||0)),'護盾')}</div>`}
function cardArt(c,mini=false){if(c?.exclusive){const src=c.role&&c.level?`/images/skill-${c.role}-${c.level}.png`:role().art;return `<span class="exclusive-card-art ${mini?'mini':''}">${uiImg(src,c.name,'')}</span>`}return `<span class="asset-slot" data-asset="card-${esc(c.id)}"></span>`}
function selectedCardsHtml(cards=[],active=-1,enemy=false){if(!cards.length)return '';return `<div class="selected-action-cards ${enemy?'enemy-cards':''}">${cards.map((c,i)=>`<div class="mini-card ${c.color} ${c.exclusive?'exclusive-card':''} ${i===active?'active':''}">${cardArt(c,true)}<b><span class="card-name-full">${esc(c.name)}</span><span class="card-name-short">${esc(String(c.name||'').slice(0,2))}</span></b><span>${'•'.repeat(i+1)}</span></div>`).join('')}</div>`}
function ultimatePanel(){if(!run||run.round<3)return '';const ready=run.ultimateEnergy>=100&&!run.ultimateUsed,ult=role().ultimate;return `<div class="ultimate-panel ${ready?'ultimate-ready':''}" style="--energy:${clamp(run.ultimateEnergy,0,100)}%"><div class="ultimate-gauge" title="必殺能量 ${Math.round(run.ultimateEnergy)}%"><i></i></div><button class="ultimate-btn" data-action="ultimate" ${ready&&run.ultimateWindow?'':'disabled'}>${run.ultimateUsed?'已施放':ready?(run.ultimateWindow?esc(ult.name):'必殺 READY'):`必殺 ${Math.round(run.ultimateEnergy)}%`}</button></div>`}
function combatHeader({playerState=run.player,enemyState=run.enemy,step=run.currentStep,showChosen=false}={}){const s=stage(),php=clamp(playerState.hp/playerState.maxHp*100,0,100),ehp=clamp(enemyState.hp/enemyState.maxHp*100,0,100),pc=run.round<=2?run.selected.map(i=>run.hand[i]):[],ec=run.round<=2?run.enemySelected.map(i=>run.enemyHand[i]):[],heroAct=step?.who==='player',enemyAct=step?.who==='enemy',cos=collectionCosmetics(collectionProgress(meta.rpg).owned),progress=run.mode==='tower'?`試煉 ${run.towerFloor}/${TOWER_MAX}`:`${run.stageIndex+1}/${STAGES.length}`,rule=run.mode==='tower'?towerRule(run.towerFloor):null;return `<header class="battle-top"><button data-action="quit" aria-label="返回" style="border:0;background:transparent;padding:0;justify-self:start;width:132px">${uiImg(ASSETS.ui.back,'返回','display:block;width:100%;height:auto;object-fit:contain;')}</button><b>${cos.title?esc(cos.title):''}</b><span>${progress}</span></header>${rule?`<div class="tower-rule-banner">${esc(rule.name)}｜${esc(rule.desc)}</div>`:''}<section class="combat-stage focus-stage ${cos.background?'collection-bg-unlocked':''} ${cos.idleFx?'collection-stars':''}"><div class="fighter hero ${heroAct?'is-acting':''}">${visual(role().art,'','fighter-art')}<div class="name-line">${esc(meta.playerName)}</div><div class="hp"><i style="width:${php}%"></i></div>${stats(playerState)}</div><div class="battle-center">${uiImg(ASSETS.ui.vs,'VS','display:block;width:min(132px,20vw);height:auto;object-fit:contain;margin:auto;')}</div><div class="fighter enemy ${enemyAct?'is-acting':''}">${visual(s.art,'','fighter-art')}<div class="name-line">${esc(s.name)}</div><div class="hp enemy-hp"><i style="width:${ehp}%"></i></div>${stats(enemyState)}</div>${showChosen&&run.round<=2?`<div class="combat-card-rail player-rail">${selectedCardsHtml(pc,heroAct?step?.slot:-1)}</div><div class="combat-card-rail enemy-rail">${selectedCardsHtml(ec,enemyAct?step?.slot:-1,true)}</div>`:''}${ultimatePanel()}</section>`}
function cardHint(c){if(c.kind==='stat')return c.stat==='crit'?`爆擊率\n${c.pct}%`:`提升\n${c.pct}%`;return CARD_HINT[c.id]||String(c.text||'').replace(/[＋+,，]/g,'\n')}
function cardHtml(c,i){const used=run.used.includes(i),order=run.selected.indexOf(i)+1;return `<button class="battle-card ${c.color} ${c.exclusive?'exclusive-card':''} ${used?'used':''} ${order?'selected':''}" data-card="${i}" ${used?'disabled':''}><span class="card-order">${order?'•'.repeat(order):''}</span>${cardArt(c)}<b>${esc(c.name)}</b><small>${esc(cardHint(c))}</small></button>`}
function ensureSelectionTimer(){if(screen!=='cards'||run.round>2)return;if(!run.selectDeadline)run.selectDeadline=Date.now()+60000;clearTimeout(selectTimeout);clearInterval(selectTicker);selectTimeout=setTimeout(()=>{if(screen!=='cards')return;autoFillSelection();confirmCards(true)},Math.max(0,run.selectDeadline-Date.now()));selectTicker=setInterval(()=>{const el=document.querySelector('[data-select-time]');if(el)el.textContent=String(Math.max(0,Math.ceil((run.selectDeadline-Date.now())/1000)))},250)}
function renderCards(){queueMicrotask(ensureSelectionTimer);return `<main class="battle-screen">${combatHeader({step:null})}<section class="card-zone"><div class="section-title"><b data-select-time style="font-size:28px">${Math.max(0,Math.ceil(((run.selectDeadline||Date.now()+60000)-Date.now())/1000))}</b></div><div class="hand-grid">${run.hand.map((c,i)=>run.used.includes(i)?'':cardHtml(c,i)).join('')}</div><div style="width:min(190px,48vw);margin:10px auto 0">${imageButton(ASSETS.ui.confirm,'確認出牌',`data-action="confirm-cards" ${run.selected.length!==3?'disabled':''}`)}</div></section></main>`}
function autoFillSelection(){const available=run.hand.map((_,i)=>i).filter(i=>!run.used.includes(i)&&!run.selected.includes(i));while(run.selected.length<3&&available.length)run.selected.push(available.splice(Math.floor(Math.random()*available.length),1)[0])}
async function confirmCards(auto=false){if(run.loadingQuestions)return;if(run.selected.length!==3){if(!auto)return;autoFillSelection()}if(run.selected.length!==3)return;clearTimeout(selectTimeout);clearInterval(selectTicker);run.selectDeadline=0;if(run.round===1&&(run.dailyQuestionIndices||[]).length!==10){run.loadingQuestions=true;try{run.dailyQuestionIndices=await fetchDailyQuestionBatch(10)}catch(err){run.loadingQuestions=false;alert(err?.message||'今日題庫讀取失敗');render();return}run.loadingQuestions=false}run.enemySelected=aiPickIndices();startQuiz()}
function startQuiz(){answerFeedback=null;run.correct=0;run.qIndex=0;run.qs=roundQuestions();run.quizStarted=performance.now();screen='quiz';render();startQuestionTimer()}
function startQuestionTimer(){clearTimeout(questionTimeout);const cur=run.qs?.[run.qIndex];speakEnglishOnce(cur?.word,`solo:${run.quizStarted}:${run.qIndex}:${cur?.word||''}`);run.questionDeadline=Date.now()+10000;questionTimeout=setTimeout(()=>answer(null,true),10000)}
function answer(value,timedOut=false){const cur=run.qs[run.qIndex];if(!cur||screen!=='quiz'||answerFeedback)return;clearTimeout(questionTimeout);const ok=!timedOut&&value===cur.answer;recordQuestionResult(cur,ok);recordVocabulary(cur.wordIndex,ok);if(ok)logDaily('correct',1);questionSyncQueue=questionSyncQueue.catch(()=>{}).then(async()=>{const r=await fetch('/api/questions/result',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({results:[{index:cur.wordIndex,answer:timedOut?'':value}]})});if(!r.ok)throw new Error('題庫同步失敗，請檢查網路後重新進入遊戲')});questionSyncQueue.catch(()=>{});if(ok)run.correct++;else run.wrongAnswers.push({word:cur.word,answer:cur.answer,selected:value||'未作答'});answerFeedback={selected:value,correct:cur.answer,ok,timedOut};render();questionTimeout=setTimeout(()=>{answerFeedback=null;run.qIndex++;if(run.qIndex>=5){const elapsed=Math.min(50000,Math.max(1,Math.round(performance.now()-run.quizStarted)-4500));resolveRound(elapsed);return}render();startQuestionTimer()},900)}
function renderQuiz(){const cur=run.qs[run.qIndex],fb=answerFeedback;const option=o=>{let bg='#e2ddd4',border='#c8c0b4',color='#29332f';if(fb){if(o===cur.answer){bg='#c8d9cb';border='#78957e';color='#23462d'}else if(o===fb.selected){bg='#e1c4c1';border='#b87873';color='#702f2b'}else{bg='#e8e4dc';border='#d3ccc1';color='#6f736f'}}return `<button class="answer-btn" data-answer="${esc(o)}" ${fb?'disabled':''} style="background:${bg};border:2px solid ${border};color:${color};">${esc(o)}</button>`};return `<main class="battle-screen combat-focus">${combatHeader({step:null,showChosen:true})}<section class="quiz-zone compact-quiz"><h1 style="display:inline-block;background:#d9ded8;border:2px solid #b9c4bc;border-radius:18px;padding:10px 22px;color:#2f3e36;">${esc(cur.word)}</h1><div class="answer-grid">${cur.options.map(option).join('')}</div></section></main>`}
function aiPickIndices(){return shuffle(run.enemyHand.map((_,i)=>i).filter(i=>!run.enemyUsed.includes(i))).slice(0,3)}
function playerCards(){return run.selected.map(i=>run.hand[i])}
function enemyCards(){return run.enemySelected.map(i=>run.enemyHand[i])}
function applyTowerHealPenalty(actor,before){if(run.mode!=='tower'||actor!==run.player)return;const mult=towerHealMultiplier(run.towerFloor),gain=Math.max(0,actor.hp-before);if(gain>0&&mult<1)actor.hp=before+Math.round(gain*mult)}
function executeCard(actor,target,card,correct,pair,slot,state,speedWin){const bond=bondMultiplier(pair,card);let boost=1;if(state.pendingBoost>1&&card.id!=='boost'){boost=state.pendingBoost;state.pendingBoost=1}if(run.mode==='tower'&&slot===0)boost*=towerFirstCardMultiplier(run.towerFloor);const before=actor.hp,logs=resolveCardAction(actor,target,card,correct,{bond,boost,offensiveIndex:state.offensiveCount,cards:pair,slotIndex:slot,speedWin});applyTowerHealPenalty(actor,before);if(card.id==='boost')state.pendingBoost=supportBoost(card,actor);if(isOffensive(card))state.offensiveCount++;afterAction(actor,target,logs);return logs}
function flatDamage(target,amount){let dmg=Math.max(0,Math.round(amount));if(target.shield>0){const block=Math.min(target.shield,dmg);target.shield-=block;dmg-=block}const dealt=Math.min(target.hp,dmg);target.hp=Math.max(0,target.hp-dmg);return dealt}
function monsterRoundStart(s,E,logs){const lv=run.level||1;
  if(run.mode==='tower'&&run.towerFloor%5===0){
    const f=run.towerFloor,P=run.player;
    if(f===5){const value=Math.round(E.maxHp*.07);E.shield+=value;logs.push(`第五層・孢子守衛：護盾 +${value}`)}
    if(f===10&&run.round===1){P.healBlock.push({pct:.35,turns:2,fresh:true});logs.push('第十層・暮影禁療：我方治療效果下降 35%')}
    if(f===15){const value=Math.round(E.maxHp*.08);E.shield+=value;logs.push(`第十五層・狂風護體：護盾 +${value}`)}
    if(f===20){const drained=Math.min(run.ultimateEnergy,12);run.ultimateEnergy-=drained;logs.push(`第二十層・魔導封印：必殺能量 -${drained}`)}
  }if(s.id==='moss'){const v=Math.round(E.maxHp*(lv>=10?.15:.12));E.shield+=v;logs.push(`孢子甲殼：護盾 +${v}`)}if(s.id==='bubble'){const low=E.hp<=E.maxHp*.5,ratio=low?(lv>=10?.20:.17):(lv>=10?.14:.11),v=Math.round(E.maxHp*ratio);E.shield+=v;logs.push(`泡泡護膜：護盾 +${v}`)}if(s.id==='beetle'){const v=Math.round(E.maxHp*(lv>=10?.18:.15));E.shield+=v;logs.push(`硬殼防禦：護盾 +${v}`)}if(s.id==='shadow'&&!E.enraged&&E.hp<=E.maxHp*(lv>=15?.60:.50)){E.enraged=true;E.atk*=lv>=15?1.32:1.25;E.poison=[];E.armorBreak=[];E.atkDown=[];E.critLock=0;logs.push(`暗影狂暴：攻擊 +${lv>=15?32:25}%，清除負面狀態`)}}
function monsterAfterPlayer(s,P,E,dealt,beforeShield,logs){if(s.id==='bubble'&&dealt>0&&E.hp>0){const absorb=Math.max(5,Math.round(dealt*.08));E.shield+=absorb;logs.push(`泡泡吸收：護盾 +${absorb}`);if(beforeShield>0&&P.hp>0){const back=flatDamage(P,Math.max(5,Math.round(dealt*.06)));logs.push(`泡膜反彈 ${back}`)}}if(s.id==='beetle'&&dealt>0&&P.hp>0){const ratio=(run.level||1)>=10?.16:.10,v=Math.min((run.level||1)>=10?70:45,Math.max(8,Math.round(dealt*ratio))),actual=flatDamage(P,v);logs.push(`硬殼反震 ${actual}`)}}
function monsterAfterEnemy(s,P,E,prevHp,slot,first,logs){const dealt=Math.max(0,prevHp-P.hp),lv=run.level||1;if(s.id==='rabbit'&&first==='enemy'&&slot===0&&P.hp>0){const actual=flatDamage(P,Math.max(12,Math.round(E.atk*.32)));logs.push(`霧影突襲 ${actual}`)}if(s.id==='rabbit'&&lv>=10&&slot===2&&P.hp>0){const actual=flatDamage(P,Math.max(10,Math.round(E.atk*.22)));logs.push(`殘影追擊 ${actual}`)}if(s.id==='shadow'&&dealt>0&&E.hp>0){const heal=Math.min(E.maxHp-E.hp,Math.round(dealt*(lv>=10?.35:.25)));if(heal>0){E.hp+=heal;logs.push(`暗影汲取 +${heal}`)}}}
function addUltimateEnergy(correct,playerFirst){const gain=correct*9+(playerFirst?8:0);run.ultimateEnergy=clamp(run.ultimateEnergy+gain,0,100)}
function resolveRound(playerMs){clearTimeout(questionTimeout);run.stats.correct+=run.correct;run.stats.total+=5;const s=stage(),pc=playerCards(),ec=enemyCards(),enemyCorrect=pick([2,3,3,4,4,5]),enemyMs=s.id==='rabbit'?2500+Math.floor(Math.random()*9500):4000+Math.floor(Math.random()*22000),first=playerMs<=enemyMs?'player':'enemy';run.lastOrder=first;addUltimateEnergy(run.correct,first==='player');run.used.push(...run.selected);run.enemyUsed.push(...run.enemySelected);const P=run.player,E=run.enemy,ps={pendingBoost:1,offensiveCount:0},es={pendingBoost:1,offensiveCount:0},sequence=[],roundStartLogs=[];monsterRoundStart(s,E,roundStartLogs);const startP=cloneFighter(P),startE=cloneFighter(E);if(first==='player')sequence.push('player','enemy','player','enemy','player','enemy');else sequence.push('enemy','player','enemy','player','enemy','player');const counts={player:0,enemy:0},steps=[];let prevP=startP,prevE=startE;for(const who of sequence){if(P.hp<=0||E.hp<=0)break;const slot=counts[who]++,beforePhp=P.hp,beforeEPool=E.hp+E.shield,beforeEShield=E.shield,beforeP=P.hp;let logs=[];if(who==='player')logs=executeCard(P,E,pc[slot],run.correct,pc,slot,ps,first==='player');else logs=executeCard(E,P,ec[slot],enemyCorrect,ec,slot,es,first==='enemy');if(who==='player'){const dealt=Math.max(0,beforeEPool-(E.hp+E.shield));run.stats.damage+=dealt;run.stats.heal+=Math.max(0,P.hp-beforeP);monsterAfterPlayer(s,P,E,dealt,beforeEShield,logs)}else monsterAfterEnemy(s,P,E,beforePhp,slot,first,logs);if(!steps.length&&roundStartLogs.length)logs.unshift(...roundStartLogs);const step={who,slot,card:who==='player'?pc[slot]:ec[slot],logs:[...logs],player:cloneFighter(P),enemy:cloneFighter(E),previous:{player:prevP,enemy:prevE}};steps.push(step);prevP=cloneFighter(P);prevE=cloneFighter(E)}if(P.hp>0){const before=P.hp,petLogs=[];applyPetRoundEnd(P,pc,petLogs);applyTowerHealPenalty(P,before);run.stats.heal+=Math.max(0,P.hp-before);if(petLogs.length&&steps.length){steps[steps.length-1].logs.push(...petLogs);steps[steps.length-1].player=cloneFighter(P)}}run.log=steps.flatMap(x=>x.logs).slice(-16);void animateSteps(steps,async()=>{if(P.hp<=0||E.hp<=0)return finishBattle();if(run.round>=2)return startAutoDuel();nextRound()})}
async function animateSteps(steps,done){const token=++flowToken;screen='action';for(const step of steps){if(token!==flowToken)return;run.currentStep=step;run.previousStepState=step.previous;render();const duration=step.who==='player'?1200:950;await playBattleStep({step,previous:step.previous,role:meta.role,duration});await sleep(65)}if(token!==flowToken)return;run.currentStep=null;await sleep(180);if(token===flowToken)await done()}
function ultimateDefinition(){const u=role().ultimate||{name:'終極一擊',mult:2.8};return {...u,mult:u.mult||((u.hits||[]).reduce((a,b)=>a+b,0)||2.8)}}
function resolveUltimateStep(){const P=run.player,E=run.enemy,previous={player:cloneFighter(P),enemy:cloneFighter(E)},u=ultimateDefinition(),old=P.atk;P.atk*=u.mult;const logs=resolveAutoBasic(P,E);P.atk=old;afterAction(P,E,logs);logs.unshift(`必殺・${u.name}`);const dealt=Math.max(0,(previous.enemy.hp+previous.enemy.shield)-(E.hp+E.shield));run.stats.damage+=dealt;run.stats.ultimates++;run.ultimateUsed=true;run.ultimateEnergy=0;return {who:'player',slot:0,cycle:run.autoRound,autoDuel:true,ultimate:true,hits:Array.isArray(u.hits)?u.hits.length:1,card:null,logs,player:cloneFighter(P),enemy:cloneFighter(E),previous}}
function waitUltimateWindow(ms=2800){return new Promise(resolve=>{run.ultimateWindow=true;run.ultimateRequested=false;ultimateResolver=v=>{run.ultimateWindow=false;ultimateResolver=null;resolve(v)};render();setTimeout(()=>{if(ultimateResolver){const r=ultimateResolver;ultimateResolver=null;run.ultimateWindow=false;r(false)}},ms)})}
async function startAutoDuel(){const token=++flowToken,first=run.lastOrder||'player';run.round=3;for(let autoRound=3;autoRound<=10&&run.player.hp>0&&run.enemy.hp>0;autoRound++){if(token!==flowToken)return;run.round=autoRound;run.autoRound=autoRound;const starter=(autoRound-3)%2===0?first:(first==='player'?'enemy':'player'),order=[starter,starter==='player'?'enemy':'player'];for(const who of order){if(token!==flowToken||run.player.hp<=0||run.enemy.hp<=0)return finishBattle();if(who==='player'&&run.ultimateEnergy>=100&&!run.ultimateUsed){const use=await waitUltimateWindow();if(token!==flowToken)return;if(use){const step=resolveUltimateStep();run.currentStep=step;screen='action';render();playUltimateIntro(meta.role);await playBattleStep({step,previous:step.previous,role:meta.role,duration:1850});await sleep(120);if(run.enemy.hp<=0)break}}
      const P=run.player,E=run.enemy,previous={player:cloneFighter(P),enemy:cloneFighter(E)},logs=[];if(who==='player'){const before=E.hp+E.shield;logs.push(...resolveAutoBasic(P,E));afterAction(P,E,logs);const dealt=Math.max(0,before-(E.hp+E.shield));run.stats.damage+=dealt;run.ultimateEnergy=clamp(run.ultimateEnergy+12+Math.min(8,Math.round(dealt/80)),0,100)}else{logs.push(...resolveAutoBasic(E,P));afterAction(E,P,logs);run.ultimateEnergy=clamp(run.ultimateEnergy+5,0,100)}const step={who,slot:0,cycle:autoRound,autoDuel:true,card:null,logs,player:cloneFighter(P),enemy:cloneFighter(E),previous};run.currentStep=step;screen='action';render();await playBattleStep({step,previous,role:meta.role,duration:who==='player'?1300:950});await sleep(80)} }
  run.currentStep=null;if(token===flowToken)finishBattle()}
function renderAction(){const step=run.currentStep,p=step?.player||run.player,e=step?.enemy||run.enemy,title=step?.ultimate?`必殺・${ultimateDefinition().name}`:step?.autoDuel?`第 ${step.cycle||3} 回合 · ${step.who==='player'?'我方':'敵方'}攻擊`:step?.card?cardSummary(step.card):'';return `<main class="battle-screen combat-focus action-screen">${combatHeader({playerState:p,enemyState:e,step,showChosen:run.round<=2})}<section class="action-status"><h1>${esc(title)}</h1><div class="battle-log current-log">${(step?.logs||[]).slice(-4).map(x=>`<p>${esc(x)}</p>`).join('')}</div></section></main>`}
function nextRound(){run.round++;run.selected=[];run.enemySelected=[];run.selectDeadline=0;run.hand=run.round===2?run.hand:dealHand(9,meta.role,run.level);screen='cards';render()}

function summaryHtml(){const st=run?.stats||freshStats(),rate=st.total?Math.round(st.correct/st.total*100):0;return `<div class="battle-summary"><div><b>${rate}%</b><span>答對率</span></div><div><b>${Math.round(st.damage)}</b><span>輸出傷害</span></div><div><b>${st.ultimates||0}</b><span>必殺</span></div></div>`}
function weaknessHtml(){const weak=recentWeaknessSummary();if(!weak.length)return `<section class="weakness-summary"><h3>弱點單字</h3><span>目前沒有待複習單字</span></section>`;return `<section class="weakness-summary"><h3>弱點單字</h3><div class="weakness-list">${weak.map(x=>`<div class="weakness-row"><b>${esc(x.word)}</b><span>${esc(x.answer)}</span></div>`).join('')}</div></section>`}
function wrongAnalysisHtml(){const wrong=run?.wrongAnswers||[];if(!wrong.length)return `<section class="wrong-analysis"><h2>錯題分析</h2><p>本次全對</p></section>`;return `<section class="wrong-analysis"><h2>錯題分析</h2>${wrong.map(x=>`<div class="wrong-item"><b>${esc(x.word)}</b><span>${esc(x.answer)}</span></div>`).join('')}</section>`}
function rewardStage(){if(run.stageRewarded)return run.lastReward;run.stageRewarded=true;const tower=run.mode==='tower',floor=run.towerFloor||1;run.lastReward=addXp(tower?100+floor*15:80+run.stageIndex*25);run.lastLoot=null;run.lastCrystals=0;if(meta.authMode!=='guest'){if(tower){const bonus=floor===20?20:floor===15?12:floor===10?8:floor===5?5:1;let next=cleanRpg(meta.rpg);next.crystals+=bonus;meta.rpg=recordTowerFloor(next,floor);run.lastCrystals=bonus}const boss=!tower&&run.stageIndex>=STAGES.length-1,mythicDrop=rollMythicLoot({boss,towerFloor:tower?floor:0,level:run.level}),lootStage=tower?(floor%5===0?3:Math.min(3,Math.floor((floor-1)/3))):Math.min(3,run.stageIndex),item=mythicDrop||rollLoot(lootStage,run.level);if(item){meta.rpg=addLoot(meta.rpg,item);run.lastLoot=item}saveMeta()}return run.lastReward}
function finishBattle(){const p=Math.max(0,Math.round(run.player.hp)),e=Math.max(0,Math.round(run.enemy.hp));if(p===e){screen='draw';render();return}const win=e<=0||(p>0&&p>e);if(!win){screen='lose';render();return}rewardStage();logDaily(run.mode==='tower'?'tower':'adventure',1);if(run.mode==='tower'){meta.daily=recordTowerBest(meta.daily,run.towerFloor);saveMeta()}screen=run.mode==='tower'&&run.towerFloor<TOWER_MAX?'stage-clear':run.mode!=='tower'&&run.stageIndex<STAGES.length-1?'stage-clear':'win';render()}
function nextStage(){if(run.mode==='tower'){const base=progressionStats(meta.role,meta.pet,run.level,meta.rpg).total;run.player.maxHp=Math.round(base.maxHp+Math.max(0,run.player.maxHp-base.maxHp)*.9);run.player.atk=Math.round(base.atk+Math.max(0,run.player.atk-base.atk)*.9);run.player.def=Math.round(base.def+Math.max(0,run.player.def-base.def)*.9);run.player.crit=Math.min(.85,base.crit+Math.max(0,run.player.crit-base.crit)*.9);run.player.shield=Math.round(Math.max(0,run.player.shield||0)*.25);run.player.hp=Math.min(run.player.maxHp,run.player.hp+Math.round(run.player.maxHp*.12));run.towerFloor=Math.min(TOWER_MAX,run.towerFloor+1)}else{run.player.hp=Math.min(run.player.maxHp,run.player.hp+Math.round(run.player.maxHp*.2));run.stageIndex++}for(const k of ['poison','armorBreak','atkDown','defBoost','healBlock'])run.player[k]=[];run.player.stun=0;run.player.critLock=0;run.player.regen=0;run.player.regenFresh=false;beginStage()}
function rewardHtml(){const r=run?.lastReward;if(!r)return '';const crystal=run.lastCrystals?`<div class="growth-reward tower-reward"><b>結晶 +${run.lastCrystals}</b><span>試煉最高 ${meta.rpg.towerBest||0}/${TOWER_MAX}</span></div>`:'';if(r.guest)return `<div class="growth-reward"><b>訪客模式</b><span>不累積 EXP</span></div>`;if(r.max)return `<div class="growth-reward"><b>Lv.${MAX_LEVEL} · 滿級</b><span>${esc(titleFor(MAX_LEVEL))}</span></div>${crystal}`;return `<div class="growth-reward"><b>EXP +${r.amount}</b><span>Lv.${meta.level} · ${esc(titleFor())}</span></div>${r.levels.length?`<div class="level-up-standalone">${uiImg(ASSETS.ui.levelUp,'升級','display:block;width:min(230px,62vw);max-height:100px;object-fit:contain;margin:0 auto;')}</div>`:''}${crystal}`}
function lootRevealHtml(){const item=run?.lastLoot;if(!item)return '';const mythic=item.quality==='mythic';return `<div class="loot-reveal-stage ${mythic?'mythic':''}"><div class="loot-beam"></div>${lootArt(item,'loot-drop-art')}</div>`}
function victoryImg(){return uiImg(ASSETS.ui.victor,'勝利','display:block;width:min(260px,72vw);max-height:120px;object-fit:contain;margin:0 auto 12px;')}
function failImg(){return uiImg(ASSETS.ui.fail,'失敗','display:block;width:min(260px,72vw);max-height:120px;object-fit:contain;margin:0 auto 12px;')}
function renderStageClear(){return `<main class="result-screen"><section class="result-card stage-clear-card">${victoryImg()}${summaryHtml()}${rewardHtml()}${lootRevealHtml()}${wrongAnalysisHtml()}${weaknessHtml()}<div class="stage-fight-btn">${imageButton(ASSETS.ui.fight,'下一戰','data-action="next-stage"')}</div></section></main>`}
function renderResult(win){const draw=win==='draw',won=win===true;return `<main class="result-screen"><section class="result-card final-result-card">${draw?'<h1>平手</h1>':won?victoryImg():failImg()}${summaryHtml()}${won?rewardHtml()+lootRevealHtml():''}${wrongAnalysisHtml()}${weaknessHtml()}<div style="width:min(112px,28vw);margin:18px auto 0">${imageButton(ASSETS.ui.back,'回首頁','data-action="home"')}</div></section></main>`}
