const socialUI=createSocialUI({app,getMeta:()=>meta,onLogin:startLineLogin,esc});
function render(){if(screen!=='community')socialUI.leave();setMusic(screen==='quiz'?'none':screen==='action'?'fight':'menu');app.innerHTML=screen==='home'?renderHome():screen==='setup'?renderSetup():screen==='equipment'?renderEquipment():screen==='pet-tree'?renderPetTree():screen==='collection'?renderCollection():screen==='quests'?renderQuests():screen==='achievements'?renderAchievements():screen==='community'?renderCommunity():screen==='cards'?renderCards():screen==='quiz'?renderQuiz():screen==='action'?renderAction():screen==='stage-clear'?renderStageClear():screen==='win'?renderResult(true):screen==='lose'?renderResult(false):screen==='draw'?renderResult('draw'):renderHome();bind();if(screen==='community')socialUI.mount();maybePlayLoot()}
function bind(){document.querySelector('[data-action="guest-login"]')?.addEventListener('click',startGuest);document.querySelector('[data-action="line-login"]')?.addEventListener('click',startLineLogin);document.querySelector('[data-action="equipment"]')?.addEventListener('click',()=>{screen='equipment';render()});document.querySelector('[data-action="pet-tree"]')?.addEventListener('click',()=>{screen='pet-tree';render()});document.querySelector('[data-action="collection"]')?.addEventListener('click',()=>{collectionTab='equipment';wordFilter='all';wordPage=0;wordSearch='';screen='collection';render()});document.querySelector('[data-action="quests"]')?.addEventListener('click',()=>{screen='quests';render()});document.querySelector('[data-action="achievements"]')?.addEventListener('click',()=>{screen='achievements';render()});document.querySelector('[data-action="community"]')?.addEventListener('click',()=>{screen='community';render()});document.querySelectorAll('[data-collection-tab]').forEach(b=>b.addEventListener('click',()=>{collectionTab=b.dataset.collectionTab==='words'?'words':'equipment';wordPage=0;render()}));document.querySelectorAll('[data-word-filter]').forEach(b=>b.addEventListener('click',()=>{wordFilter=b.dataset.wordFilter;wordPage=0;render()}));document.querySelectorAll('[data-word-speak]').forEach(b=>b.addEventListener('click',()=>speakCollectedWord(Number(b.dataset.wordSpeak))));document.querySelectorAll('[data-word-page]').forEach(b=>b.addEventListener('click',()=>{wordPage=Math.max(0,wordPage+Number(b.dataset.wordPage));render()}));document.querySelector('[data-word-search-apply]')?.addEventListener('click',()=>{wordSearch=String(document.querySelector('[data-word-search-field]')?.value||'').trim().slice(0,40);wordPage=0;render()});document.querySelector('[data-word-search-field]')?.addEventListener('keydown',event=>{if(event.key==='Enter'){wordSearch=String(event.currentTarget.value||'').trim().slice(0,40);wordPage=0;render()}});document.querySelectorAll('[data-equip-title]').forEach(b=>b.addEventListener('click',()=>chooseTitle(b.dataset.equipTitle)));document.querySelector('[data-community-share]')?.addEventListener('click',()=>{void shareCommunity(false)});document.querySelector('[data-community-copy]')?.addEventListener('click',()=>{void shareCommunity(true)});document.querySelector('[data-community-pk]')?.addEventListener('click',startPk);document.querySelectorAll('[data-claim-quest]').forEach(b=>b.addEventListener('click',()=>claimDailyReward(b.dataset.claimQuest)));document.querySelectorAll('[data-claim-achievement]').forEach(b=>b.addEventListener('click',()=>claimDailyReward(b.dataset.claimAchievement,true)));document.querySelector('[data-daily-chest]')?.addEventListener('click',openDailyChest);document.querySelector('[data-action="tower"]')?.addEventListener('click',startTower);document.querySelector('[data-action="setup-back"]')?.addEventListener('click',()=>{screen='setup';render()});document.querySelector('[data-action="reset-pet-tree"]')?.addEventListener('click',()=>{if(!Object.values(meta.rpg.petSkills||{}).some(x=>x?.length))return;if(!confirm('重置三隻寵物的全部技能樹並返還技能點？寵物強化與覺醒不會重置。'))return;meta.rpg=resetPetSkills(meta.rpg);saveMeta();render()});document.querySelectorAll('[data-enhance-equip]').forEach(b=>b.addEventListener('click',()=>{const item=meta.rpg.inventory.find(x=>x.id===b.dataset.enhanceEquip);if(!item)return;const info=equipmentEnhanceInfo(item);if(info.level>=10||meta.rpg.crystals<info.cost)return;if(!confirm(`強化 +${info.level} → +${info.level+1}？\n消耗 ${info.cost} 結晶，成功率 ${Math.round(info.chance*100)}%。失敗降 1 級。`))return;const result=enhanceEquipment(meta.rpg,item.id);if(!result.ok)return;meta.rpg=result.rpg;enhanceFeedback=result.success?`強化成功 +${result.after}`:`強化失敗，降為 +${result.after}`;saveMeta();render()}));document.querySelectorAll('[data-equip]').forEach(b=>b.addEventListener('click',()=>{meta.rpg=equipItem(meta.rpg,b.dataset.equip);saveMeta();render()}));document.querySelectorAll('[data-unequip]').forEach(b=>b.addEventListener('click',()=>{meta.rpg=unequipItem(meta.rpg,b.dataset.unequip);saveMeta();render()}));document.querySelectorAll('[data-synthesize]').forEach(b=>b.addEventListener('click',()=>{meta.rpg=synthesizeItem(meta.rpg,b.dataset.synthesize);saveMeta();render()}));document.querySelectorAll('[data-crystallize]').forEach(b=>b.addEventListener('click',()=>{const item=meta.rpg.inventory.find(x=>x.id===b.dataset.crystallize);if(!item||!confirm(`將「${item.name}」轉換為 ${crystalValue(item)} 個結晶？`))return;meta.rpg=crystallizeItem(meta.rpg,item.id);saveMeta();render()}));document.querySelectorAll('[data-pet-enhance]').forEach(b=>b.addEventListener('click',()=>{meta.rpg=enhancePet(b.dataset.petEnhance,meta.rpg);saveMeta();render()}));document.querySelectorAll('[data-pet-skill]').forEach(b=>b.addEventListener('click',()=>{const [id,node]=b.dataset.petSkill.split('|');meta.rpg=unlockPetSkill(id,node,meta.level,meta.rpg);saveMeta();render()}));document.querySelector('[data-action="start"]')?.addEventListener('click',startRun);document.querySelector('[data-action="pk"]')?.addEventListener('click',startPk);document.querySelector('[data-action="quit"]')?.addEventListener('click',()=>{clearFlow();screen='setup';render()});document.querySelector('[data-action="confirm-cards"]')?.addEventListener('click',()=>confirmCards(false));document.querySelector('[data-action="next-stage"]')?.addEventListener('click',nextStage);document.querySelector('[data-action="home"]')?.addEventListener('click',()=>{clearFlow();screen='home';render()});document.querySelector('[data-action="ultimate"]')?.addEventListener('click',()=>{if(run?.ultimateWindow&&run.ultimateEnergy>=100&&!run.ultimateUsed&&ultimateResolver){const r=ultimateResolver;ultimateResolver=null;run.ultimateWindow=false;r(true)}});document.querySelectorAll('[data-role]').forEach(b=>b.addEventListener('click',()=>{meta.role=b.dataset.role;saveMeta();render()}));document.querySelectorAll('[data-pet]').forEach(b=>b.addEventListener('click',()=>{meta.pet=b.dataset.pet;saveMeta();render()}));document.querySelectorAll('[data-card]').forEach(b=>b.addEventListener('click',()=>{const i=Number(b.dataset.card);if(run.used.includes(i))return;const at=run.selected.indexOf(i);if(at>=0)run.selected.splice(at,1);else if(run.selected.length<3)run.selected.push(i);render()}));document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>answer(b.dataset.answer,false)))}

render();
void resumeLineLogin();
